import{_ as i,a0 as u,w as a,s,ao as l,I as n,x as t,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"戴文的Linux內核專題：19 配置內核 (15) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：19 配置內核 (15) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：19 配置內核 (15) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：19 配置內核 (15) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/19 The Linux Kernel--Configuring the Kernel Part 15","title":"戴文的Linux內核專題：19 配置內核 (15)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/19 The Linux Kernel--Configuring the Kernel Part 15.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/19 The Linux Kernel--Configuring the Kernel Part 15.md"};function L(C,e,x,m,S,D){const p=u("Link");return a(),s("div",null,[e[11]||(e[11]=l(`<h1 id="戴文的linux內核專題-19-配置內核-15" tabindex="-1">戴文的Linux內核專題：19 配置內核 (15) <a class="header-anchor" href="#戴文的linux內核專題-19-配置內核-15" aria-label="Permalink to “戴文的Linux內核專題：19 配置內核 (15)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.578/" alt=""></p><p>你好！在這篇Linux系列文章中，我們將繼續配置USB網絡驅動。接着我們將進入輸入設備。</p><p>首先，我們可以啓用/禁用&quot;Multi-purpose USB Networking Framework&quot;，這允許連接筆記本到桌面系統上。</p><p>下面，可以啓用/禁用ASIX USB-to-Ethernet適配器驅動(ASIX AX88xxx Based USB 2.0 Ethernet Adapters)。</p><p>那麼，還有一個ASIX適配器驅動(ASIX AX88179/178A USB 3.0/2.0 to Gigabit Ethernet)。</p><p>注意：通常地，最好將適配器驅動作為模組加入。</p><p>通信設備類規範(Communication Device Class specification)在這個驅動中提供(CDC Ethernet support (smart devices such as cable modems))。這個規範用於USB調製解調器。Linux系統可以將USB網絡接口識別為以太網網絡接口並且指定為&quot;ethX&quot;,這裏的&quot;X&quot;是以太設備編號。</p><p>下面是一個與上面類似的規範(CDC EEM support)。CDC EEM代表的是&quot;Communication Device Class Ethernet Emulation Model&quot;(通信設備類以太網仿真模型)。</p><p>CDC網絡控制模型(NCM)同樣有一個驅動提供了規範(CDC NCM support)。</p><p>這個驅動提供了&quot;CDC MBIM (Mobile Broadband Interface Model)&quot;規範同樣也在Linux內核中(CDC MBIM support)。</p><p>下面，有一些供貨商/設備特定驅動用於不同的USB網絡設備和芯片組。</p><p>在這之後，有一個用於USB網絡設備的通用驅動，它不需要任何特殊的驅動(Simple USB Network Links (CDC Ethernet subset))。</p><p>再説一次，還有更多的驅動用於供貨商特定設備。</p><pre><code>有趣的事實：Linux被用於製作James Cameron的電影&quot;泰坦尼克&quot;的特效。
</code></pre><p>&quot;CDC Phonet support&quot;是用於使用Phonet的Nokia USB調製解調器。(譯註：Phonet是Nokia開發的面向數據包的通信協議,僅用於Nokia maemo/meego產品)</p><p>現在，我們可以進入使用802.11規範的無線局域網驅動了。</p><p>主要地，這裏有一個供貨商/設備特定驅動列表。</p><p>&quot;SoftLED Support&quot;控制着關於Wifi卡/設備的LED燈。</p><p>一些芯片組支持的SDIO在這個驅動中(Atheros ath6kl SDIO support)。SDIO是用於無線SD卡的SD(Secure Digital)規範的擴展。SDIO代表的是&quot;Secure Digital Input/Output&quot;</p><p>內核開發者可能注意到一些無線設備可以支持QoS。QoS代表&quot;Quality of Service&quot;(服務質量)。這個特性給予網絡傳輸優先級。假設需要通過網絡傳輸兩組數據。只有一個可以先發送。QoS會先發送最重要的數據。</p><pre><code>有趣的事實：技術上來説，Linux並不是一個操作系統。Linux是一種內核而GNU/Linux才是操作系統。
</code></pre><p>WAN卡需要&quot;Generic HDLC layer&quot;。HDLC代表&quot;High-Level Data Link Control&quot;(高級數據鏈路控制)。這是一個數據鏈路層協議。</p><p>原生HDLC可以通過&quot;Raw HDLC support&quot;驅動啓用。</p><p>&quot;Raw HDLC Ethernet device support&quot;驅動允許HDLC層模擬以太網。</p><p>cHDLC驅動提供了一個HDLC的擴展，同樣也稱作Cisco HDLC(Cisco HDLC support)。</p><p>Linux內核同樣也提供了一個HDLC的&quot;Frame Relay support&quot;(幀中繼)驅動。幀中繼是2層協議。</p><p>HDLC同樣支持PPP(Synchronous Point-to-Point Protocol (PPP) support)和X.25(X.25 protocol support)。</p><p>接下來，這個驅動提供了DLCI下的幀中繼(Frame Relay DLCI support)。</p><p>&quot;LAPB over Ethernet driver&quot;創建一個允許用户在以太網上使用LAPB的點到點連接到另一台計算機的設備文件。這個設備文件對於第一個此類設備通常是/dev/lapb0。</p><p>用這個驅動，X.25幀可以通過電話線發送(X.25 async driver)。特別地，這個驅動允許X.25使用異步串行。</p><p>對於ISA SBNI12-xx有一種特殊的驅動(Granch SBNI12 Leased Line adapter support)。這種卡對於租用線路的調製解調器是一種便宜的替代。</p><p>下一個驅動允許使用並行連接攜帶已安排的流量(Multiple line feature support)。這允許Linux系統更加有效地在SBNI12適配器上管理並行連接。一些Linux用户聲稱這個驅動雙倍加速了他們的速度。然而，這個我沒有親身測試瞭解。</p><p>接下來，可以配置&quot;IEEE 802.15.4 drivers&quot;。這個是對於慢速WAN設備。這是一個控制媒體和無線網絡物理層的標準。這個規範在不同的大洲使用不同的頻率。不如，在歐洲，這類無線設備會使用868.0-868.6MHz的頻率。</p><p>這個目錄中的第一個設定是fake LR-WPAN驅動(Fake LR-WPAN driver with several interconnected devices)。LR-WPAN代表&quot;Low-Rate Wireless Personal Area Network&quot;(低速無線個人網絡)。</p><p>有趣的事實：目前內核中只有大約2%的代碼是由Linus Torvalds寫的。</p><p>VMware使用vmxnet3虛擬以太網需要這個驅動(VMware VMXNET3 ethernet driver)。當在為大量用户編譯內核時，最好將這個啓用為一個模組，因為一些人可能並不希望在VMware上使用以太網。</p><p>Hyper-V虛擬網絡需要這個驅動(Microsoft Hyper-V virtual network driver)。你可能想知道這個是否與微軟的Hyper-V相同？是的，Linux支持Hyper-V。</p><p>數字電話服務ISDN由這個驅動提供(ISDN support)。ISDN代表&quot;Integrated Services Digital Network&quot;(綜合業務數字網)。在法國，ISDN被稱為RNIS，代表&quot; Réseau numérique à intégration de services&quot;。有一台ISDN適配器，計算機可以開始並接收語音呼叫。這允許計算機用來做因待機或者其他一些電話服務設備。ISDN同樣也可以攜帶視頻信息。</p><p>現在，我們可以進入輸入設備了(Input device support)。這些是給計算機信息的設備。鼠標和鍵盤是最常被使用和了解的輸入設備。掃描儀是另外一種輸入設備的例子。</p><p>首先是一個支持不同觸覺反饋設備的驅動(Support for memoryless force-feedback devices)。比如，許多遊戲控制器的震動就是一種觸覺反饋。</p><p>一些輸入設備會檢測硬件的狀態(Polled input device skeleton)。這類行為需要這個驅動。</p><p>使用稀疏鍵盤映射的輸入設備需要這個驅動(Sparse keymap support library)。鍵盤映射是鍵盤的佈局信息。</p><p>下面，是另外一種鍵盤映射(Matrix keymap support library)。</p><p>注意：當為廣泛的用户組編譯內核時，包含大多數或者全部輸入設備作為模組，因為通常不知道用户可能插到計算機上的設備類型。</p><pre><code>有趣的事實：Vanilla內核就是Linux自己的原始內核，是未改變的狀態。
</code></pre><p>&quot;Mouse interface&quot;對於鼠標創建了兩個不同的設備文件。這兩個設備文件是/dev/input/mouseX 和 /dev/input/mice。</p><p>下一個驅動創建了一個psaux設備文件並且它是/dev/input/mice的別名 (Provide legacy /dev/psaux device)。psaux設備文件是/dev/psaux。</p><p>如果系統有一塊數位板，那麼需要設置水平分辨率(Horizontal screen resolution)和垂直分辨率(Vertical screen resolution)。數位板是一種支持允許用户繪畫的觸控筆的觸摸屏。另外的觸摸屏無法支持如此複雜的輸入。</p><p>下一個驅動支持操縱桿和遊戲手柄(Joystick interface)。這個驅動會創建/dev/input/jsX文件。</p><p>&quot;Event interface&quot;驅動允許輸入設備通過dev/input/eventX訪問。</p><p>&quot;Event debugging&quot;驅動會輸出所有的輸入事件到系統日誌中。除了要調試系統否則不要以任何理由啓用它。顯然地，這麼做為了性能原因，但是我這麼建議禁用的主要原因是安全目的。所有的按鍵都會被明文記錄下來包括密碼。</p><p>下面，列出了不同的鍵盤(Keyboards)配置驅動，接下來是鼠標(Mice)驅動和操縱桿和遊戲手柄(joystick/gamepad)驅動。</p><p>在這之後，列出了不同特定的平板硬件/供貨商的不同驅動(Tablets)。在這之後是觸摸屏的驅動列表。</p><p>最後一組輸入設備驅動是對於特定硬件和供貨商的雜項驅動列表(Miscellaneous devices)。</p><p>這個系列的下一篇文章會討論輸入端口。不要忘記閲讀這個系列的其他文章和這個網站。謝謝！</p><p><strong>致粉絲: 謝謝</strong>你們的郵件告訴我你們對這些文章的喜愛。</p><hr>`,58)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),o(p,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-15.4793/"},{default:r(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-15.4793/",-1)])]),_:1})]),n("p",null,[e[4]||(e[4]=t("譯者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:r(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:r(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),o(p,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const g=i(d,[["render",L]]);export{h as __pageData,g as default};
